import csv, glob, json, os, sys, zipfile
from multiprocessing import Pool

BAND = 25.0


def lines_of(fh):
    tail = b''
    while True:
        buf = fh.read(1 << 24)
        if not buf:
            break
        buf = tail + buf
        parts = buf.split(b'\n')
        tail = parts.pop()
        yield from parts
    if tail.strip():
        yield tail


def one(job):
    zp, out = job
    if os.path.exists(out):
        return out, 0, "есть"
    rows = []
    bids, asks = {}, {}
    cur = None
    n_err = 0

    def snap(m):
        if not bids or not asks:
            return
        bb, ba = max(bids), min(asks)
        if ba <= bb:
            return
        mid = (bb + ba) / 2
        lo, hi = mid * (1 - BAND / 1e4), mid * (1 + BAND / 1e4)
        rows.append((m, bb, ba, sum(q for p, q in bids.items() if p >= lo), sum(q for p, q in asks.items() if p <= hi)))

    zf = zipfile.ZipFile(zp)
    fh = zf.open(zf.namelist()[0])
    prev = 0.0
    for raw in lines_of(fh):
        if not raw.strip():
            continue
        try:
            d = json.loads(raw)
            te = float(d.get('cts') or d['ts'])
            typ = d['type']
            dd = d['data']
        except Exception:
            n_err += 1
            continue
        if te < prev:
            te = prev
        prev = te
        m = int(te // 60000) * 60
        if cur is None:
            cur = m
        if m != cur:
            snap(cur)  # состояние на конец минуты cur
            cur = m
        if typ == 'snapshot':
            bids = {float(p): float(s) for p, s in dd.get('b', [])}
            asks = {float(p): float(s) for p, s in dd.get('a', [])}
        else:
            for p, s in dd.get('b', ()):
                if float(s) == 0.0:
                    bids.pop(float(p), None)
                else:
                    bids[float(p)] = float(s)
            for p, s in dd.get('a', ()):
                if float(s) == 0.0:
                    asks.pop(float(p), None)
                else:
